var l=[{title:`Що означає «відмова»`,text:`Концентрична відмова: це коли ви намагаєтеся, але не можете завершити ще одне повторення підйому. Технічна відмова настає раніше, коли ви вже не можете зберегти заплановану амплітуду чи безпечний рух. У складній вправі ви можете досягти технічної відмови задовго до того, як цільові м’язи досягнуть повної м’язової відмови.`},{title:`Важке тренування без відмови`,text:`У позиційній заяві ACSM 2026 тренування до миттєвої відмови не давало надійно кращих результатів у силі, гіпертрофії чи потужності. Підходи, що закінчуються з приблизно двома-трьома повтореннями в запасі, часто дають корисний тренувальний стимул із меншою втомою. Наскільки близько до відмови слід підходити, залежить від вашої цілі, навантаження, вправи, досвіду та ситуації.`},{title:`Ризик залежить від вправи`,text:`Підхід близько до відмови на стабільному тренажері чи в малоризиковій ізолюючій вправі дуже відрізняється від такого в важкому присіді зі штангою, жимі над головою без опори чи незнайомому вибуховому русі. Втрата брейсингу, втрата контролю при опусканні чи відсутність безпечного способу зупинитися: це причини завершити підхід. Якщо ви тренуєтеся самі без страхувального обладнання, це ще одна причина лишати повторення в запасі.`},{title:`Приклад`,text:`Якщо ви тягнете 15 кг на дванадцять чистих повторень і думаєте, що могли б зробити ще два, підхід має близько 2 RIR. Вам не потрібно доводити це, змушуючи тринадцяте й чотирнадцяте повторення. Досвідчений може інколи довести підхід близько до відмови на безпечному тренажері з конкретної причини, але це не має бути планом на кожне заняття. Прагніть до зусилля й якості, які можна повторювати, і не вважайте відмову досягненням, яке треба збирати.`},{title:`Коли зупинитися`,text:`Завершуйте будь-який підхід, якщо виникає незвичний біль, запаморочення, раптова слабкість або ви не можете контролювати рух. Нормальне м’язове зусилля відрізняється від цих тривожних ознак.`}];var i=[{label:`Позиційна заява ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Дослідження RPE на основі RIR`,url:`https://pubmed.ncbi.nlm.nih.gov/26049792/`}];var n={sections:l,sources:i};export{n as default,l as sections,i as sources};